# ============================================================
# Script: 06_endothelial_subcluster_analysis.R
# Project: Adipose scRNA-seq analysis
# Purpose: Subcluster endothelial cells and perform subcluster-level DE analysis
# Author: Yi Hu
# ============================================================

# This script provides the core endothelial cell subcluster analysis workflow.
# It starts from the annotated integrated Seurat object generated by
# 03_clustering_annotation.R.
#
# Input:
#   results/annotation/seurat_integrated_annotated.rds
#
# Output:
#   results/ec_subcluster/seurat_ec_subcluster_annotated.rds
#   results/ec_subcluster/ec_subcluster_markers_all.csv
#   results/ec_subcluster/ec_subcluster_markers_top20.csv
#   results/ec_subcluster/ec_subcluster_counts_by_condition.csv
#   results/ec_subcluster/ec_subcluster_fraction_by_condition.csv
#   results/ec_subcluster/ec_subcluster_DE_combined.csv
#   results/ec_subcluster/IPA_input/

# -----------------------------
# 1. Load packages
# -----------------------------

suppressPackageStartupMessages({
  library(Seurat)
  library(tidyverse)
  library(tibble)
  library(forcats)
})

# -----------------------------
# 2. Define input and output paths
# -----------------------------

input_file <- "results/annotation/seurat_integrated_annotated.rds"
output_dir <- "results/ec_subcluster"

dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)

# -----------------------------
# 3. Load annotated Seurat object
# -----------------------------

seurat_obj <- readRDS(input_file)

# The major cell type annotation should have been added in:
# scripts/03_clustering_annotation.R

Idents(seurat_obj) <- "cell_type"

# -----------------------------
# 4. Subset endothelial cells
# -----------------------------

ec_obj <- subset(
  x = seurat_obj,
  idents = "Endothelial Cell"
)

ec_cell_counts <- ec_obj@meta.data %>%
  count(condition, name = "n_cells")

write.csv(
  ec_cell_counts,
  file = file.path(output_dir, "ec_cell_counts_by_condition.csv"),
  row.names = FALSE
)

# -----------------------------
# 5. Re-integrate / re-cluster endothelial cells
# -----------------------------

# Endothelial cells were reprocessed independently to resolve EC subclusters.
# Samples are split by condition and integrated using SCT integration.

ec_list <- SplitObject(
  object = ec_obj,
  split.by = "condition"
)

ec_list <- lapply(
  X = ec_list,
  FUN = function(obj) {
    SCTransform(
      object = obj,
      assay = "RNA",
      verbose = FALSE
    )
  }
)

ec_features <- SelectIntegrationFeatures(
  object.list = ec_list,
  nfeatures = 3000
)

ec_list <- PrepSCTIntegration(
  object.list = ec_list,
  anchor.features = ec_features
)

ec_anchors <- FindIntegrationAnchors(
  object.list = ec_list,
  normalization.method = "SCT",
  anchor.features = ec_features
)

ec_integrated <- IntegrateData(
  anchorset = ec_anchors,
  normalization.method = "SCT"
)

DefaultAssay(ec_integrated) <- "integrated"

# -----------------------------
# 6. Dimensionality reduction
# -----------------------------

ec_integrated <- RunPCA(
  object = ec_integrated,
  verbose = FALSE
)

pdf(file.path(output_dir, "ec_elbow_plot.pdf"), width = 5, height = 4)
ElbowPlot(ec_integrated, ndim = 30)
dev.off()

n_pcs <- 20

ec_integrated <- RunUMAP(
  object = ec_integrated,
  reduction = "pca",
  dims = 1:n_pcs
)

# -----------------------------
# 7. Graph-based clustering
# -----------------------------

ec_integrated <- FindNeighbors(
  object = ec_integrated,
  reduction = "pca",
  dims = 1:n_pcs,
  verbose = FALSE
)

# The final endothelial subcluster annotation was based on resolution 0.6.

selected_resolution <- 0.6

ec_integrated <- FindClusters(
  object = ec_integrated,
  resolution = selected_resolution,
  verbose = FALSE
)

ec_integrated$ec_cluster <- Idents(ec_integrated)

# Minimal QC UMAPs.

p_ec_cluster <- DimPlot(
  object = ec_integrated,
  reduction = "umap",
  label = TRUE
) +
  ggtitle("Endothelial cell subclusters")

ggsave(
  filename = file.path(output_dir, "ec_umap_by_cluster.pdf"),
  plot = p_ec_cluster,
  width = 6,
  height = 5
)

p_ec_condition <- DimPlot(
  object = ec_integrated,
  reduction = "umap",
  group.by = "condition"
) +
  ggtitle("Endothelial cells by condition")

ggsave(
  filename = file.path(output_dir, "ec_umap_by_condition.pdf"),
  plot = p_ec_condition,
  width = 6,
  height = 5
)

# -----------------------------
# 8. Identify EC subcluster markers
# -----------------------------

DefaultAssay(ec_integrated) <- "SCT"

ec_integrated <- PrepSCTFindMarkers(ec_integrated)

Idents(ec_integrated) <- "seurat_clusters"

ec_subcluster_markers <- FindAllMarkers(
  object = ec_integrated,
  only.pos = TRUE,
  min.pct = 0.25,
  logfc.threshold = 0.25,
  test.use = "wilcox"
)

write.csv(
  ec_subcluster_markers,
  file = file.path(output_dir, "ec_subcluster_markers_all.csv"),
  row.names = FALSE
)

ec_subcluster_markers_top20 <- ec_subcluster_markers %>%
  group_by(cluster) %>%
  slice_max(order_by = avg_log2FC, n = 20, with_ties = FALSE)

write.csv(
  ec_subcluster_markers_top20,
  file = file.path(output_dir, "ec_subcluster_markers_top20.csv"),
  row.names = FALSE
)

# -----------------------------
# 9. Review canonical EC subcluster markers
# -----------------------------

# Marker genes used to support endothelial subcluster annotation.
# This concise marker list records the biological basis of annotation,
# while publication-quality figure styling was performed separately.

ec_marker_genes <- c(
  # Pan-endothelial markers
  "Pecam1", "Cdh5", "Kdr", "Vwf", "Flt1",
  
  # Lymphatic endothelial cells
  "Lyve1", "Prox1", "Pdpn",
  
  # Inflammatory / immune-responsive endothelial programs
  "Icam1", "Vcam1", "Sele", "Selp", "Cd74", "Cxcl9", "Rsad2",
  
  # Vascular / angiogenic markers
  "Nos3", "Tek", "Angpt2",
  
  # Mesenchymal-like EC markers
  "Col1a1", "Col3a1", "Tagln",
  
  # Metabolic / membrane-associated markers
  "Fmo2", "Aqp1", "Car4"
)

ec_marker_genes <- ec_marker_genes[
  ec_marker_genes %in% rownames(ec_integrated)
]

p_ec_marker_dotplot <- DotPlot(
  object = ec_integrated,
  features = ec_marker_genes
) +
  RotatedAxis() +
  ggtitle("Canonical markers for EC subcluster annotation")

ggsave(
  filename = file.path(output_dir, "ec_subcluster_marker_dotplot.pdf"),
  plot = p_ec_marker_dotplot,
  width = 12,
  height = 5
)

# -----------------------------
# 10. Annotate EC subclusters
# -----------------------------

# The cluster-to-subcluster mapping below follows the final EC annotation
# used in the analysis.
#
# REC: Resting Endothelial Cells
# IREC: Immune-responsive Endothelial Cells
# IEC: Inflammatory Endothelial Cells
# VEC: Vascular Endothelial Cells
# MesEC: Mesenchymal-like Endothelial Cells
# MbEC: Metabolic Endothelial Cells
# LEC: Lymphatic Endothelial Cells

ec_subcluster_annotation <- tibble::tribble(
  ~cluster, ~ec_subcluster,
  "0",      "REC",
  "1",      "REC",
  "5",      "REC",
  "9",      "REC",
  "2",      "IREC",
  "6",      "IREC",
  "8",      "IREC",
  "11",     "IREC",
  "12",     "IREC",
  "3",      "MesEC",
  "4",      "IEC",
  "7",      "VEC",
  "10",     "MbEC",
  "14",     "LEC",
  "13",     "Unassigned"
)

write.csv(
  ec_subcluster_annotation,
  file = file.path(output_dir, "ec_cluster_to_subcluster_annotation.csv"),
  row.names = FALSE
)

metadata <- ec_integrated@meta.data %>%
  as.data.frame() %>%
  tibble::rownames_to_column("barcode") %>%
  mutate(seurat_clusters = as.character(seurat_clusters)) %>%
  left_join(
    ec_subcluster_annotation,
    by = c("seurat_clusters" = "cluster")
  ) %>%
  tibble::column_to_rownames("barcode")

ec_integrated$ec_subcluster <- metadata[
  rownames(ec_integrated@meta.data),
  "ec_subcluster"
]

ec_integrated$ec_subcluster <- factor(
  ec_integrated$ec_subcluster,
  levels = c(
    "REC",
    "IREC",
    "MesEC",
    "IEC",
    "VEC",
    "MbEC",
    "LEC",
    "Unassigned"
  )
)

# -----------------------------
# 11. Remove unassigned EC clusters
# -----------------------------

# In the original analysis, the unassigned cluster was excluded from
# downstream EC subcluster analysis.

Idents(ec_integrated) <- "ec_subcluster"

ec_integrated <- subset(
  x = ec_integrated,
  idents = "Unassigned",
  invert = TRUE
)

ec_integrated$ec_subcluster <- droplevels(ec_integrated$ec_subcluster)

# -----------------------------
# 12. Create subcluster-condition groups
# -----------------------------

# Example values:
# REC-Chow, REC-HFSC, IREC-Chow, IREC-HFSC

ec_integrated$DE_subgroup <- paste0(
  ec_integrated$ec_subcluster,
  "-",
  ec_integrated$condition
)

ec_integrated$DE_subgroup <- factor(ec_integrated$DE_subgroup)

# -----------------------------
# 13. Summarize EC subcluster composition
# -----------------------------

ec_subcluster_counts <- ec_integrated@meta.data %>%
  count(condition, ec_subcluster, name = "n_cells")

write.csv(
  ec_subcluster_counts,
  file = file.path(output_dir, "ec_subcluster_counts_by_condition.csv"),
  row.names = FALSE
)

ec_subcluster_fraction <- ec_subcluster_counts %>%
  group_by(condition) %>%
  mutate(fraction = n_cells / sum(n_cells)) %>%
  ungroup()

write.csv(
  ec_subcluster_fraction,
  file = file.path(output_dir, "ec_subcluster_fraction_by_condition.csv"),
  row.names = FALSE
)

# Minimal annotated UMAP.

p_ec_annotated <- DimPlot(
  object = ec_integrated,
  reduction = "umap",
  group.by = "ec_subcluster",
  label = TRUE
) +
  ggtitle("Annotated EC subclusters")

ggsave(
  filename = file.path(output_dir, "ec_umap_annotated_subclusters.pdf"),
  plot = p_ec_annotated,
  width = 6,
  height = 5
)

# -----------------------------
# 14. Differential expression within EC subclusters
# -----------------------------

DefaultAssay(ec_integrated) <- "RNA"

# For Seurat v5 objects, join RNA layers before differential expression.
ec_integrated <- JoinLayers(ec_integrated)

ec_integrated <- NormalizeData(
  object = ec_integrated,
  assay = "RNA",
  verbose = FALSE
)

Idents(ec_integrated) <- "DE_subgroup"

condition_1 <- "HFSC"
condition_2 <- "Chow"

ec_subclusters <- c(
  "REC",
  "IREC",
  "MesEC",
  "IEC",
  "VEC",
  "MbEC",
  "LEC"
)

ec_de_results_list <- list()

for (subcluster in ec_subclusters) {
  
  message("Running DE analysis for EC subcluster: ", subcluster)
  
  ident_1 <- paste(subcluster, condition_1, sep = "-")
  ident_2 <- paste(subcluster, condition_2, sep = "-")
  
  if (!(ident_1 %in% levels(Idents(ec_integrated))) ||
      !(ident_2 %in% levels(Idents(ec_integrated)))) {
    
    warning("Skipping ", subcluster, ": one or both comparison groups are missing.")
    next
  }
  
  markers <- FindMarkers(
    object = ec_integrated,
    ident.1 = ident_1,
    ident.2 = ident_2,
    logfc.threshold = 0,
    min.pct = 0.1,
    test.use = "wilcox"
  )
  
  markers_df <- markers %>%
    as.data.frame() %>%
    rownames_to_column(var = "gene") %>%
    arrange(p_val_adj) %>%
    mutate(
      cell_type = "Endothelial Cell",
      subcluster = subcluster,
      comparison = paste(condition_1, "vs", condition_2)
    )
  
  write.csv(
    markers_df,
    file = file.path(
      output_dir,
      paste0("EC_", subcluster, "_", condition_1, "_vs_", condition_2, "_DE.csv")
    ),
    row.names = FALSE
  )
  
  ec_de_results_list[[subcluster]] <- markers_df
}

# -----------------------------
# 15. Combine EC subcluster DE results
# -----------------------------

ec_de_combined <- bind_rows(ec_de_results_list)

write.csv(
  ec_de_combined,
  file = file.path(output_dir, "ec_subcluster_DE_combined.csv"),
  row.names = FALSE
)

# -----------------------------
# 16. Generate filtered DEG table
# -----------------------------

# This table can be used for pathway analysis input.
# Thresholds should match the manuscript Methods section.

ec_de_filtered <- ec_de_combined %>%
  filter(
    p_val_adj < 0.05,
    abs(avg_log2FC) >= 0.25
  )

write.csv(
  ec_de_filtered,
  file = file.path(output_dir, "ec_subcluster_DE_filtered_FDR005_logFC025.csv"),
  row.names = FALSE
)

# -----------------------------
# 17. Export IPA input tables
# -----------------------------

ipa_output_dir <- file.path(output_dir, "IPA_input")
dir.create(ipa_output_dir, recursive = TRUE, showWarnings = FALSE)

for (subcluster in unique(ec_de_filtered$subcluster)) {
  
  ipa_table <- ec_de_filtered %>%
    filter(subcluster == !!subcluster) %>%
    select(gene, avg_log2FC, p_val, p_val_adj)
  
  write.csv(
    ipa_table,
    file = file.path(
      ipa_output_dir,
      paste0("EC_", subcluster, "_IPA_input.csv")
    ),
    row.names = FALSE
  )
}

# -----------------------------
# 18. Save EC subcluster object
# -----------------------------

saveRDS(
  ec_integrated,
  file = file.path(output_dir, "seurat_ec_subcluster_annotated.rds")
)

# -----------------------------
# 19. Session information
# -----------------------------

sink(file.path(output_dir, "session_info_ec_subcluster.txt"))
sessionInfo()
sink()